		b := node("a_same", "app/same.py", graph.FamilyCalls, 1, Umbra, TierNone, false)
		c := node("c_other", "app/aaa.py", graph.FamilyCalls, 1, Umbra, TierNone, false)
		for _, n := range []*Node{a, b, c} {
