			t.Fatalf("order[%d] = %s %s, want %s %s", i, first[i].Symbol.File, first[i].Symbol.Name, want[i], gotNames[i])
		}
	}
	for run := 0; run < 5; run++ {
		again := mk()
		SortDocket(again)
		for i := range again {
			if again[i].Symbol.Name != first[i].Symbol.Name {
